# statiq·ref v0.3.56: Auswahl oben wie calc/size (Menü mit Filter) statt Seitenleiste; „Auf dieser Seite“, Themen-Pager, Handy-Menü, Bausteine ablauf/eqLine/filterBox. Ohne Playwright: SKIP.
import os, sys, asyncio
HERE=os.path.dirname(os.path.abspath(__file__)); HTML='file://'+os.path.abspath(os.path.join(HERE,'..','ref.html'))
try:
    from playwright.async_api import async_playwright
except ImportError:
    print('SKIP Playwright nicht installiert'); sys.exit(0)
fails=0
def check(name, ok, info=''):
    global fails; fails+=not ok; print('OK  ' if ok else 'FAIL', f'{name:66}', str(info)[:150])
async def main():
    async with async_playwright() as p:
        br=await p.chromium.launch(); pg=await br.new_page(viewport={'width':1440,'height':900}); errs=[]
        pg.on('pageerror', lambda e: errs.append(str(e)))
        await pg.goto(HTML); await pg.evaluate("localStorage.clear()"); await pg.reload(); await pg.wait_for_timeout(400)
        g=await pg.evaluate("""(()=>{const p=document.getElementById('pick').getBoundingClientRect(), m=document.getElementById('main').getBoundingClientRect();
          return [!document.getElementById('sidebar'), Math.abs(p.left-m.left)<2, p.width>600, document.getElementById('pick-g').textContent, document.getElementById('pick-t').textContent]})()""")
        check('Desktop 1440: keine Seitenleiste, Auswahl oben über dem Inhalt (wie calc/size)', g[0] and g[1] and g[2] and g[3]=='Wissen' and g[4]=='Thema wählen', g)
        g=await pg.evaluate("[!!document.querySelector('.home-tiles, #main .tile'), !!document.querySelector('.home-hint'), !!document.getElementById('search')]")
        check('Startseite Desktop: nur die Suche, keine Kacheln (Fächer stehen in der Auswahl oben, v0.3.72)', g==[False,False,True], g)
        await pg.click('#pick-btn'); await pg.wait_for_timeout(150)
        n=await pg.evaluate("[document.getElementById('pick').classList.contains('open'), document.querySelectorAll('#pick-menu .pick-item').length, document.querySelectorAll('#pick-menu .pick-group').length, document.querySelectorAll('#pick-menu .pick-k').length]")
        check('Auswahl öffnet das Menü: Fächer, Kapitel und alle Themen', n[0] and n[1]>100 and n[2]>=8 and n[3]>=30, n)
        await pg.fill('#pick-q','Bernoulli'); await pg.wait_for_timeout(150)
        vis=await pg.evaluate("[...document.querySelectorAll('#pick-menu .pick-item')].filter(a=>a.offsetParent).map(a=>a.textContent.trim())")
        check('Filter „Bernoulli“ zeigt nur passende Themen', 0<len(vis)<=3 and any('Bernoulli' in v for v in vis), vis)
        await pg.fill('#pick-q','xyzxyz'); await pg.wait_for_timeout(100)
        check('Filter ohne Treffer: Hinweis „Kein Thema gefunden“', await pg.is_visible('#pick-menu .pick-none'))
        await pg.fill('#pick-q','Bernoulli'); await pg.wait_for_timeout(100)
        link=pg.locator('#pick-menu a.pick-item', has_text='Bernoulli').first; await link.click(); await pg.wait_for_timeout(400)
        st=await pg.evaluate("[location.hash, document.querySelectorAll('#toc a').length, !!document.querySelector('.topic-pager'), document.getElementById('pick-t').textContent, document.getElementById('pick-g').textContent, document.getElementById('pick').classList.contains('open')]")
        check('Klick im Menü öffnet das Thema und schließt das Menü', 'bernoulli' in st[0] and not st[5], st)
        check('„Auf dieser Seite“ listet die Abschnitte', st[1]>=2, st[1])
        check('Auswahl zeigt klein Fach · Kapitel, groß das Thema', 'Bernoulli' in st[3] and st[4].startswith('Wasserbau · '), st[3:5])
        await pg.click('#pick-btn'); await pg.wait_for_timeout(150)
        act=await pg.evaluate("[document.querySelector('#pick-menu .pick-item.active')?.textContent||'', [...document.querySelectorAll('#pick-menu .pick-group.open')].map(g=>g.dataset.f)]")
        check('Menü: aktuelles Thema markiert, nur das aktuelle Fach offen', 'Bernoulli' in act[0] and act[1]==['wasserbau'], act)
        await pg.click('#pick-menu .pick-group[data-f="baustatik"] .pick-head'); await pg.wait_for_timeout(100)
        check('Fach aufklappen lässt das andere offen (kein Akkordeon mehr)', await pg.evaluate("[...document.querySelectorAll('#pick-menu .pick-group.open')].map(g=>g.dataset.f).join()")=='baustatik,wasserbau')
        await pg.keyboard.press('Escape'); await pg.wait_for_timeout(100); await pg.click('#pick-btn'); await pg.wait_for_timeout(150)
        check('Menü wieder öffnen: aufgeklappte Fächer bleiben offen', await pg.evaluate("[...document.querySelectorAll('#pick-menu .pick-group.open')].map(g=>g.dataset.f).join()")=='baustatik,wasserbau')
        await pg.click('#pick-menu .pick-group[data-f="baustatik"] .pick-head'); await pg.wait_for_timeout(100)
        check('Erneuter Klick klappt nur dieses Fach zu', await pg.evaluate("[...document.querySelectorAll('#pick-menu .pick-group.open')].map(g=>g.dataset.f).join()")=='wasserbau')
        await pg.keyboard.press('Escape'); await pg.wait_for_timeout(100)
        check('Escape schließt das Menü', not await pg.evaluate("document.getElementById('pick').classList.contains('open')"))
        await pg.click('#pick-btn'); await pg.wait_for_timeout(100); await pg.mouse.click(1300, 850); await pg.wait_for_timeout(100)
        check('Klick daneben schließt das Menü', not await pg.evaluate("document.getElementById('pick').classList.contains('open')"))
        ok=await pg.evaluate("""(()=>{return [...document.querySelectorAll('#toc a')].every(a=>!!document.getElementById(a.dataset.id))})()""")
        check('Links in „Auf dieser Seite“ zeigen auf vorhandene Abschnitte', ok)
        await pg.goto(HTML+'#/wasserbau/hydrodynamik'); await pg.wait_for_timeout(300)
        check('Kapitelseite: klein das Fach, groß das Kapitel', await pg.evaluate("[document.getElementById('pick-g').textContent, document.getElementById('pick-t').textContent]")==['Wasserbau', await pg.evaluate("FAECHER.wasserbau.kapitel.hydrodynamik.title")])
        # Bausteine
        h=await pg.evaluate("ablauf('Test',['§Schritt 1','!Hinweis','M = q · l² / 8 = 10 · 25 / 8 = 31,25 kNm'])")
        check('ablauf(): Überschrift, Hinweis, Formelkette zeilenweise', 'Schritt 1' in h and 'Hinweis' in h and h.count('class="eq-r')>=3, h)
        h=await pg.evaluate("eqLine('Beispiel: das ist ein Satz mit = Zeichen')")
        check('eqLine(): Fließtext wird nicht zerlegt', not h or 'eq-r' not in h, h)
        # Handy
        await pg.set_viewport_size({'width':390,'height':844}); await pg.goto(HTML+'#/wasserbau/hydrodynamik/bernoulli'); await pg.wait_for_timeout(300)
        g=await pg.evaluate("[document.documentElement.scrollWidth, getComputedStyle(document.querySelector('#main .page-head'),'::after').content, getComputedStyle(document.getElementById('toc')).display, document.querySelector('#main > :first-child').id]")
        check('Handy: kein Querscrollen, Auswahl zuoberst, Seitenkopf ohne Pfeil, kein Inhaltsverzeichnis', g[0]<=390 and g[1] in ('none','normal') and g[2]=='none' and g[3]=='pick', g)
        await pg.click('#main .page-head'); await pg.wait_for_timeout(150)
        check('Handy: Tipp auf den Seitenkopf öffnet nichts mehr', not await pg.evaluate("document.getElementById('pick').classList.contains('open')"))
        await pg.click('#pick-btn'); await pg.wait_for_timeout(200)
        r=await pg.evaluate("(()=>{const m=document.getElementById('pick-menu').getBoundingClientRect(); return [m.left>=0, m.right<=390, document.documentElement.scrollWidth]})()")
        check('Handy: Menü passt in die Breite', r[0] and r[1] and r[2]<=390, r)
        await pg.locator('#pick-menu a.pick-item', has_text='Manning').first.click(); await pg.wait_for_timeout(300)
        check('Handy: Themenwahl öffnet das Thema und schließt das Menü', 'manning' in (await pg.evaluate("location.hash")).lower() or 'gerinne' in (await pg.evaluate("location.hash")).lower() and not await pg.evaluate("document.getElementById('pick').classList.contains('open')"), await pg.evaluate("location.hash"))
        await pg.goto(HTML+'#/'); await pg.wait_for_timeout(300)
        check('Startseite Handy: Suche ohne Kacheln', await pg.evaluate("!!document.getElementById('search') && !document.querySelector('.home-tiles, #main .tile')"))
        check('keine Skriptfehler', not errs, errs)
        await br.close()
asyncio.run(main())
print('FAILS:', fails)
